def _coerce_resource_value(name: str, value: Any) -> float:
    """Validate and coerce a single resource quantity to a non-negative float.

    Booleans are explicitly rejected since ``bool`` is a subclass of ``int`` but
    is not a meaningful resource quantity.
    """
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"Resource {name!r} must be a number, got {value!r}.")
    value = float(value)
    if value < 0:
        raise ValueError(
            f"Resource {name!r} must be non-negative, got {value}."
        )
    return value


class BundleConfig(BaseModel):
    """A resource bundle used for placement.

    ``CPU`` and ``GPU`` default to ``0.0``. Arbitrary additional named resources
    (e.g. ``TPU``) may be supplied as extra keyword arguments and are stored as
    floats. All values are coerced to floats and validated to be non-negative
    numbers.
    """

    model_config = ConfigDict(extra="allow")

    CPU: float = 0.0
    GPU: float = 0.0

    @model_validator(mode="before")
    @classmethod
    def _validate_resources(cls, data: Any) -> Any:
        if not isinstance(data, dict):
            return data
        return {
            name: _coerce_resource_value(name, value) for name, value in data.items()
        }


class PlacementGroupConfig(BaseModel):
    """A placement group configuration.

    Exactly one of ``bundles`` (an explicit list of bundles) or
    ``bundle_per_worker`` (a single bundle replicated per worker) must be
    provided. ``strategy`` must be one of the valid placement group strategies.
    """

    bundles: Optional[List[BundleConfig]] = None
    bundle_per_worker: Optional[BundleConfig] = None
    strategy: str

    @field_validator("strategy")
    @classmethod
    def _validate_strategy(cls, value: str) -> str:
        if value not in VALID_PLACEMENT_GROUP_STRATEGIES:
            raise ValueError(
                f"Invalid strategy {value!r}. Must be one of "
                f"{sorted(VALID_PLACEMENT_GROUP_STRATEGIES)}."
            )
        return value

